.orders-table-scroll {
  overflow: auto;
  max-height: calc(100vh - 220px);
  min-height: 320px;
  border: 1px solid var(--g-color-line-generic);
  border-radius: var(--g-border-radius-l);
  background: var(--g-color-base-background);
}

.orders-table {
  width: 100%;
  min-width: 880px;
  border-collapse: separate;
  border-spacing: 0;
  font: var(--g-text-body-2-font);
  color: var(--g-color-text-primary);
}

.orders-table th,
.orders-table td {
  padding: 0 var(--g-spacing-3);
  height: 44px;
  border-bottom: 1px solid var(--g-color-line-generic);
  text-align: left;
  white-space: nowrap;
  vertical-align: middle;
}

.orders-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--g-color-base-background);
  font: var(--g-text-subheader-1-font);
  color: var(--g-color-text-secondary);
  font-weight: 500;
  user-select: none;
}

.orders-table .align-end {
  text-align: right;
}

/* Column widths. Table is wider than the viewport on narrow screens and scrolls horizontally. */
.col-select { width: 48px; }
.col-number { width: 110px; }
.col-customer { width: 260px; }
.col-status { width: 170px; }
.col-date { width: 130px; }
.col-city { width: 160px; }
.col-items { width: 100px; }
.col-total { width: 140px; }

/* Column header drag & drop */
.column-header {
  cursor: grab;
  border-radius: var(--g-border-radius-s);
}

.column-header:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: -2px;
}

.column-header:active {
  cursor: grabbing;
}

.column-header.is-dragging {
  opacity: 0.4;
}

.column-header.is-drop-before {
  box-shadow: inset 3px 0 0 var(--g-color-line-brand);
}

.column-header.is-drop-after {
  box-shadow: inset -3px 0 0 var(--g-color-line-brand);
}

/* Rows */
.orders-table tbody tr {
  cursor: pointer;
  user-select: none;
}

.orders-table tbody tr:not(.group-row):hover td {
  background: var(--g-color-base-simple-hover);
}

.orders-table tbody tr.is-selected td {
  background: var(--g-color-base-selection);
}

.orders-table tbody tr.is-selected:hover td {
  background: var(--g-color-base-selection-hover);
}

.empty-cell {
  height: 120px;
  text-align: center;
  color: var(--g-color-text-secondary);
  cursor: default;
}

/* Selection checkbox cell. Clicks go to the row/cell, see OrdersTable.tsx. */
.select-cell {
  width: 48px;
  padding-left: var(--g-spacing-3) !important;
  padding-right: 0 !important;
  cursor: pointer;
}

.select-control {
  display: inline-flex;
  pointer-events: none;
}

/* Grouping */
.group-row td {
  background: var(--g-color-base-generic-ultralight);
  height: 40px;
}

.group-row:hover td {
  background: var(--g-color-base-generic-hover) !important;
}

.group-row td:not(.select-cell) {
  padding: 0;
}

.group-toggle {
  display: flex;
  align-items: center;
  gap: var(--g-spacing-2);
  width: 100%;
  height: 40px;
  padding: 0 var(--g-spacing-3);
  border: 0;
  background: transparent;
  font: var(--g-text-subheader-1-font);
  color: var(--g-color-text-primary);
  cursor: pointer;
  text-align: left;
}

.group-toggle:focus-visible {
  outline: 2px solid var(--g-color-line-focus);
  outline-offset: -2px;
}

.group-count {
  color: var(--g-color-text-secondary);
  font: var(--g-text-body-2-font);
}

/* Cell content */
.tabular {
  font-variant-numeric: tabular-nums;
}

.cell-stack {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}

.cell-secondary {
  color: var(--g-color-text-secondary);
  font: var(--g-text-caption-1-font);
}

