import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5173/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));

const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

await page.goto(URL, { waitUntil: 'networkidle' });
await page.waitForSelector('.orders-table');

// 1. Initial state: sidebar expanded, orders page open, grouped by status
check('sidebar expanded by default', (await page.locator('.sidebar.is-collapsed').count()) === 0);
const navLabels = await page.locator('.sidebar-item-label').allTextContents();
check('nav sections', JSON.stringify(navLabels) === JSON.stringify(['Главная', 'Пользователи', 'Заказы', 'Настройки']), navLabels.join(', '));
check('orders section current', (await page.locator('.sidebar-item.is-current').textContent()) === 'Заказы');
const groupCount = await page.locator('.group-row').count();
check('grouped by status (5 statuses)', groupCount === 5, `groups=${groupCount}`);
const dataRows = await page.locator('.orders-table tbody tr:not(.group-row)').count();
check('600 order rows rendered', dataRows === 600, `rows=${dataRows}`);

await page.screenshot({ path: '/tmp/shot/01-orders-grouped.png' });

// 2. Collapse a group
const firstGroupBtn = page.locator('.group-toggle').first();
const rowsBefore = await page.locator('.orders-table tbody tr:not(.group-row)').count();
await firstGroupBtn.click();
const rowsAfter = await page.locator('.orders-table tbody tr:not(.group-row)').count();
const expanded = await firstGroupBtn.getAttribute('aria-expanded');
check('group collapse hides rows', rowsAfter < rowsBefore && expanded === 'false', `${rowsBefore} -> ${rowsAfter}`);
await firstGroupBtn.click();
check('group expand restores rows', (await page.locator('.orders-table tbody tr:not(.group-row)').count()) === rowsBefore);

// 3. Row selection: click, ctrl-free toggle, shift range
const rows = page.locator('.orders-table tbody tr:not(.group-row)');
await rows.nth(0).click();
await rows.nth(1).click();
check('two rows selected by click', (await page.locator('tr.is-selected').count()) === 2);
await rows.nth(0).click(); // toggle off
check('click toggles row off', (await page.locator('tr.is-selected').count()) === 1);
await rows.nth(0).click(); // back on, anchor = row 0
await rows.nth(4).click({ modifiers: ['Shift'] });
check('shift-click selects range 0..4', (await page.locator('tr.is-selected').count()) === 5, `selected=${await page.locator('tr.is-selected').count()}`);
const selBar = await page.locator('.table-toolbar').textContent();
check('toolbar shows selected count', selBar.includes('Выбрано: 5'), selBar.trim());

// 4. Select whole group via group checkbox
await page.locator('.group-row').first().locator('.select-cell').click();
const groupSelected = await page.locator('.group-row').first().locator('input[type=checkbox]').isChecked();
check('group checkbox selects group', groupSelected);
await page.locator('.group-row').first().locator('.select-cell').click();
check('group checkbox again deselects group', !(await page.locator('.group-row').first().locator('input[type=checkbox]').isChecked()));

// 5. Select all via header
await page.locator('thead .select-cell').click();
check('header select-all selects 600', (await page.locator('tr.is-selected').count()) === 600);
await page.locator('.table-toolbar button').click(); // Снять выделение
check('clear selection', (await page.locator('tr.is-selected').count()) === 0);

// 6. Column reordering by mouse drag: move "Сумма" to position of "Клиент"
const headerTexts = async () => (await page.locator('thead th').allTextContents()).map((t) => t.trim());
const before = await headerTexts();
await page.locator('thead th', { hasText: 'Сумма' }).dragTo(page.locator('thead th', { hasText: 'Клиент' }));
const afterDrag = await headerTexts();
check('drag column: total moved before customer', afterDrag.indexOf('Сумма') === before.indexOf('Клиент') && afterDrag[0] === '', JSON.stringify(afterDrag));
// body cells follow the header
const firstRowCells = await page.locator('.orders-table tbody tr:not(.group-row)').first().locator('td').allTextContents();
check('body cells follow column order', firstRowCells.length === 8, `${firstRowCells.length} cells`);
await page.screenshot({ path: '/tmp/shot/02-after-drag.png' });

// 7. Keyboard column move: focus "Город" and Alt+ArrowLeft
await page.locator('thead th', { hasText: 'Город' }).focus();
const beforeKey = await headerTexts();
await page.keyboard.press('Alt+ArrowLeft');
const afterKey = await headerTexts();
const iCity = beforeKey.indexOf('Город');
check('Alt+ArrowLeft moves column left', afterKey[iCity - 1] === 'Город', JSON.stringify(afterKey));

// 8. Ungroup
await page.locator('.page-header .switch, .page-header label').first().click();
check('ungrouping removes group rows', (await page.locator('.group-row').count()) === 0);

// 9. Collapse sidebar
await page.locator('.sidebar-toggle').click();
check('sidebar collapsed', (await page.locator('.sidebar.is-collapsed').count()) === 1);
const collapsedLabels = await page.locator('.sidebar-item-label').count();
check('labels hidden when collapsed', collapsedLabels === 0);
await page.screenshot({ path: '/tmp/shot/03-collapsed.png' });

// 10. Navigate to home via icon button
await page.locator('.sidebar-item', { hasText: '' }).first().click();
check('home page renders', (await page.locator('.stat-tile').count()) === 4);
await page.screenshot({ path: '/tmp/shot/04-home.png' });

await browser.close();

console.log(results.join('\n'));
console.log('--- console errors/warnings:', errors.length);
for (const e of errors.slice(0, 20)) console.log(e);

