import http from 'node:http';
import { readFileSync } from 'node:fs';
const dir = '/tmp/shot/node_modules/@fontsource/inter/files/';
http.createServer((req, res) => {
  const name = req.url.split('/').pop().split('?')[0];
  try {
    const body = readFileSync(dir + name);
    res.writeHead(200, { 'content-type': 'font/woff2', 'access-control-allow-origin': '*', 'content-length': body.length });
    res.end(body);
  } catch { res.writeHead(404); res.end(); }
